function monitorHealth(data=watchData,failed=watchFetchFailed,now=Date.now()){
  const sources=Array.isArray(data?.sources)?data.sources:[];
  const good=sources.filter(sourceIsGood).length;
  const stamp=Date.parse(data?.generated_at||'');
  const age=Number.isFinite(stamp)?(now-stamp)/3600000:null;
  if(!data||!sources.length)return {tone:'warning',text:failed?'监测记录暂未载入，可重试':'监测记录载入中',good,total:sources.length};
  if(failed)return {tone:'warning',text:'刷新失败，当前显示上次记录',good,total:sources.length};
  if(age===null||age>12||age < -0.1)return {tone:'warning',text:'运行记录已延迟，暂不能判断新变化',good,total:sources.length};
  return {tone:good===sources.length?'ok':'warning',text:good===sources.length?'本轮公开网页检查完成':`${sources.length-good} 个来源未成功，覆盖不完整`,good,total:sources.length};
}
function runWindow(now=Date.now()){const runs=watchRuns().filter(r=>{const d=Date.parse(r.checked_at);return Number.isFinite(d)&&d<=now&&now-d<86400000});return {count:runs.length,complete:runs.filter(r=>r.failure_count===0).length}}
function sourceFreshness(s,now=Date.now()){const stamp=Date.parse(s.last_success||'');let failures=0;for(const run of watchRuns().slice().reverse()){const item=(run.sources||[]).find(x=>x.id===s.id);if(!item||sourceIsGood(item))break;failures++}if(!Number.isFinite(stamp))return '尚无成功快照'+(failures?' · 连续 '+failures+' 轮失败':'');const hours=Math.max(0,Math.floor((now-stamp)/3600000));return (sourceIsGood(s)&&hours<24?'成功检查距今 ':'历史快照距今 ')+hours+' 小时'+(failures?' · 连续 '+failures+' 轮失败':'')+(hours>=24||!sourceIsGood(s)?'；不能判断当前变化':'')}
function watchMini(){const health=monitorHealth(),window=runWindow();return '<section class="watch-mini"><div><span class="eyebrow">持续跟踪 / 最近实际运行</span><h2>下一次，重点看发生了什么变化</h2><p>'+escapeHtml(shortDate(watchData?.generated_at))+' · '+escapeHtml(health.text)+'</p></div><div class="watch-facts"><div><strong>'+(health.total?health.good+' / '+health.total:'—')+'</strong><span>本轮公开网页抓取成功</span></div><div><strong>'+changesList().length+'</strong><span>累计文本变化 · 尚需复核</span></div><div><strong>'+window.count+' 轮</strong><span>最近 24 小时实际检查</span></div></div><a class="action-link" href="#watch">查看变化、实际记录与覆盖范围 ↗</a></section>'}
