function sourceStatus(s){const state=sourceIsGood(s)?s.change_type:s.status;return ({initial:'首次基线',unchanged:'抓到的页面文本未变',content_changed:'正文有变化',ok:'检查成功',success:'检查成功',error:'检查失败',blocked:'暂不可采'})[state]||state||'待检查'}
